#!/usr/bin/env python3
"""Reject incomplete scaling evidence generated by the real GL draw path."""
import pathlib
import subprocess
import sys

root = pathlib.Path(__file__).resolve().parents[1]
logs = pathlib.Path(sys.argv[1])
# The previous checker accepts these deliberately broken runtime draws.
previous = subprocess.run(['git', 'show', 'HEAD:tests/textoescala_confere.py'],
                          check=True, capture_output=True, text=True).stdout
if 'statistics.median' in previous:
    namespace = {'__name__': 'regression_before'}
    exec(previous, namespace)
    for name in ('unscaled-text', 'missing-button'):
        namespace['compare'](name, logs / 'base.log', logs / f'{name}.log', 1.3)
    print('FAIL reproduced: previous checker accepted incomplete runtime evidence')
for name in ('scaled', 'unscaled-text', 'unscaled-button', 'missing-button'):
    result = subprocess.run([sys.executable, str(root / 'tests/textoescala_confere.py'),
                             name, str(logs / 'base.log'), str(logs / f'{name}.log'), '1.3'],
                            capture_output=True, text=True)
    assert (result.returncode == 0) == (name == 'scaled'), result.stdout + result.stderr
    print(f'PASS runtime proof: {name} rc={result.returncode}')
assert '${NV_BASE:-f22761e28}' in (root / 'tests/textoescala_prova.sh').read_text()
print('PASS integration baseline default: f22761e28')
